import{_ as u,a0 as g,w as e,s as a,I as i,x as t,a1 as r,A as n,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何衡量一個開源社區的健康度 | LCTT x X-CMD","titleTemplate":false,"description":"如何衡量一個開源社區的健康度 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何衡量一個開源社區的健康度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何衡量一個開源社區的健康度 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190811 How to measure the health of an open source community","title":"如何衡量一個開源社區的健康度","tag":"201908","desc":""},"relativePath":"201908/20190811 How to measure the health of an open source community.md","filePath":"[post].md"}'),p={name:"201908/20190811 How to measure the health of an open source community.md"};function m(d,l,f,S,T,C){const o=g("Link");return e(),a("div",null,[l[35]||(l[35]=i("h1",{id:"如何衡量一個開源社區的健康度",tabindex:"-1"},[t("如何衡量一個開源社區的健康度 "),i("a",{class:"header-anchor",href:"#如何衡量一個開源社區的健康度","aria-label":"Permalink to “如何衡量一個開源社區的健康度”"},"​")],-1)),l[36]||(l[36]=i("blockquote",null,[i("p",null,"這比較複雜。")],-1)),l[37]||(l[37]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/19/184719nz3xuazppzu3vwcg.jpg",alt:""})],-1)),l[38]||(l[38]=i("p",null,"作為一個經常管理軟件開發團隊的人，多年來我一直關注度量指標。一次次，我發現自己領導團隊使用一個又一個的項目平台（例如 Jira、GitLab 和 Rally）生成了大量可測量的數據。從那時起，我已經及時投入了大量時間從記錄平台中提取了有用的指標，並採用了一種我們可以理解的格式，然後使用這些指標對開發的許多方面做出更好的選擇。",-1)),i("p",null,[l[3]||(l[3]=t("今年早些時候，我有幸在 ",-1)),r(o,{href:"https://www.linuxfoundation.org/"},{default:n(()=>[...l[0]||(l[0]=[t("Linux 基金會",-1)])]),_:1}),l[4]||(l[4]=t("遇到了一個名為",-1)),i("ruby",null,[r(o,{href:"https://chaoss.community/"},{default:n(()=>[...l[1]||(l[1]=[t("開源軟件社區健康分析",-1)])]),_:1}),l[2]||(l[2]=i("rt",null,"Community Health Analytics for Open Source Software",-1))]),l[5]||(l[5]=t("（CHAOSS）的項目。該項目側重於從各種來源收集和豐富指標，以便開源社區的利益相關者可以衡量他們項目的健康狀況。",-1))]),l[39]||(l[39]=s('<h3 id="chaoss-介紹" tabindex="-1">CHAOSS 介紹 <a class="header-anchor" href="#chaoss-介紹" aria-label="Permalink to “CHAOSS 介紹”">​</a></h3><p>隨着我對該項目的基本指標和目標越來越熟悉，一個問題在我的腦海中不斷翻滾。什麼是“健康”的開源項目，由誰來定義？</p><p>特定角色的人認為健康的東西可能另一個角色的人就不會這樣認為。似乎可以用 CHAOSS 收集的細粒度數據進行市場細分實驗，重點關注對特定角色可能最有意義的背景問題，以及 CHAOSS 收集哪些指標可能有助於回答這些問題。</p><p>CHAOSS 項目創建並維護了一套開源應用程序和度量標準定義，使得這個實驗具有可能性，這包括：</p><ul><li>許多基於服務器的應用程序，用於收集、聚合和豐富度量標準（例如 Augur 和 GrimoireLab）。</li><li>ElasticSearch、Kibana 和 Logstash（ELK）的開源版本。</li><li>身份服務、數據分析服務和各種集成庫。</li></ul><p>在我過去的一個程序中，有六個團隊從事於不同複雜程度的項目，我們找到了一個簡潔的工具，它允許我們從簡單（或複雜）的 JQL 語句中創建我們想要的任何類型的指標，然後針對這些指標開發計算。在我們注意到之前，我們僅從 Jira 中就提取了 400 多個指標，而且還有更多指標來自手動的來源。</p><p>在項目結束時，我們認定這 400 個指標中，大多數指標在<em>以我們的角色</em>做出決策時並不重要。最終，只有三個對我們非常重要：“缺陷去除效率”、“已完成的條目與承諾的條目”，以及“每個開發人員的工作進度”。這三個指標最重要，因為它們是我們對自己、客户和團隊成員所做出的承諾，因此是最有意義的。</p><p>帶着這些通過經驗得到的教訓和對什麼是健康的開源項目的問題，我跳進了 CHAOSS 社區，開始建立一套角色，以提供一種建設性的方法，從基於角色的角度回答這個問題。</p><p>CHAOSS 是一個開源項目，我們嘗試使用民主共識來運作。因此，我決定使用<ruby>組成分子<rt>constituent</rt></ruby>這個詞而不是利益相關者，因為它更符合我們作為開源貢獻者的責任，以創建更具共生性的價值鏈。</p><p>雖然創建此組成模型的過程採用了特定的“目標-問題-度量”方法，但有許多方法可以進行細分。CHAOSS 貢獻者已經開發了很好的模型，可以按照矢量進行細分，例如項目屬性（例如，個人、公司或聯盟）和“失敗容忍度”。在為 CHAOSS 開發度量定義時，每個模型都會提供建設性的影響。</p><p>基於這一切，我開始構建一個誰可能關心 CHAOSS 指標的模型，以及每個組成分子在 CHAOSS 的四個重點領域中最關心的問題：</p>',11)),i("ul",null,[i("li",null,[r(o,{href:"https://github.com/chaoss/wg-diversity-inclusion"},{default:n(()=>[...l[6]||(l[6]=[t("多樣性和包容性",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-evolution"},{default:n(()=>[...l[7]||(l[7]=[t("演化",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-risk"},{default:n(()=>[...l[8]||(l[8]=[t("風險",-1)])]),_:1})]),i("li",null,[r(o,{href:"https://github.com/chaoss/wg-value"},{default:n(()=>[...l[9]||(l[9]=[t("價值",-1)])]),_:1})])]),l[40]||(l[40]=s('<p>在我們深入研究之前，重要的是要注意 CHAOSS 項目明確地將背景判斷留給了實施指標的團隊。什麼是“有意義的”和“什麼是健康的？”的答案預計會因團隊和項目而異。CHAOSS 軟件的現成儀表板儘可能地關注客觀指標。在本文中，我們關注項目創始人、項目維護者和貢獻者。</p><h3 id="項目組成分子" tabindex="-1">項目組成分子 <a class="header-anchor" href="#項目組成分子" aria-label="Permalink to “項目組成分子”">​</a></h3><p>雖然這絕不是這些組成分子可能認為重要的問題的詳盡清單，但這些選擇感覺是一個好的起點。以下每個“目標-問題-度量”標準部分與 CHAOSS 項目正在收集和彙總的指標直接相關。</p><p>現在，進入分析的第 1 部分！</p><h4 id="項目創始人" tabindex="-1">項目創始人 <a class="header-anchor" href="#項目創始人" aria-label="Permalink to “項目創始人”">​</a></h4><p>作為<strong>項目創始人</strong>，我<strong>最</strong>關心：</p>',6)),i("ul",null,[l[16]||(l[16]=s("<li>我的項目<strong>對其他人有用嗎？</strong>通過以下測量： <ul><li>隨着時間推移有多少復刻？ <ul><li><strong>指標：</strong>存儲庫復刻數。</li></ul></li><li>隨着時間的推移有多少貢獻者？ <ul><li><strong>指標：</strong>貢獻者數量。</li></ul></li><li>貢獻淨質量。 <ul><li><strong>指標：</strong>隨着時間的推移提交的錯誤。</li><li><strong>指標：</strong>隨着時間的迴歸。</li></ul></li><li>項目的財務狀況。 <ul><li><strong>指標：</strong>隨着時間的推移的捐贈/收入。</li><li><strong>指標：</strong>隨着時間的推移的費用。</li></ul></li></ul></li><li>我的項目對其它人的<strong>可見</strong>程度？ <ul><li>有誰知道我的項目？別人認為它很整潔嗎？ <ul><li><strong>指標：</strong>社交媒體上的提及、分享、喜歡和訂閲的數量。</li></ul></li><li>有影響力的人是否瞭解我的項目？ <ul><li><strong>指標：</strong>貢獻者的社會影響力。</li></ul></li><li>人們在公共場所對項目有何評價？是正面還是負面？ <ul><li><strong>指標：</strong>跨社交媒體渠道的情感（關鍵字或 NLP）分析。</li></ul></li></ul></li><li>我的項目<strong>可行性</strong>程度？ <ul><li>我們有足夠的維護者嗎？該數字是隨着時間的推移而上升還是下降？ <ul><li><strong>指標：</strong>維護者數量。</li></ul></li><li>改變速度如何隨時間變化？ <ul><li><strong>指標：</strong>代碼隨時間的變化百分比。</li><li><strong>指標：</strong>拉取請求、代碼審查和合並之間的時間。</li></ul></li></ul></li>",3)),i("li",null,[l[11]||(l[11]=t("我的項目的",-1)),r(o,{href:"https://github.com/chaoss/wg-diversity-inclusion"},{default:n(()=>[...l[10]||(l[10]=[t("多樣化 ＆ 包容性",-1)])]),_:1}),l[12]||(l[12]=s("如何？ <ul><li>我們是否擁有有效的公開行為準則（CoC）？ <ul><li><strong>度量標準：</strong> 檢查存儲庫中的 CoC 文件。</li></ul></li><li>與我的項目相關的活動是否積極包容？ <ul><li><strong>指標：</strong>關於活動的票務政策和活動包容性行為的手動報告。</li></ul></li><li>我們的項目在可訪問性上做的好不好？ <ul><li><strong>指標：</strong>驗證發佈的文字會議紀要。</li><li><strong>指標：</strong>驗證會議期間使用的隱藏式字幕。</li><li><strong>指標：</strong>驗證在演示文稿和項目前端設計中色盲可訪問的素材。</li></ul></li></ul>",2))]),i("li",null,[l[14]||(l[14]=t("我的項目代表了多少",-1)),r(o,{href:"https://github.com/chaoss/wg-value"},{default:n(()=>[...l[13]||(l[13]=[t("價值",-1)])]),_:1}),l[15]||(l[15]=s("？ <ul><li>我如何幫助組織瞭解使用我們的項目將節省多少時間和金錢（勞動力投資） <ul><li><strong>指標：</strong>倉庫的議題、提交、拉取請求的數量和估計人工費率。</li></ul></li><li>我如何理解項目創建的下游價值的數量，以及維護我的項目對更廣泛的社區的重要性（或不重要）？ <ul><li><strong>指標：</strong>依賴我的項目的其他項目數。</li></ul></li><li>為我的項目做出貢獻的人有多少機會使用他們學到的東西來找到合適的工作崗位，以及在哪些組織（即生活工資）？ <ul><li><strong>指標：</strong>使用或貢獻此庫的組織數量。</li><li><strong>指標：</strong>使用此類項目的開發人員的平均工資。</li><li><strong>指標：</strong>與該項目匹配的關鍵字的職位發佈計數。</li></ul></li></ul>",2))])]),l[41]||(l[41]=s('<h3 id="項目維護者" tabindex="-1">項目維護者 <a class="header-anchor" href="#項目維護者" aria-label="Permalink to “項目維護者”">​</a></h3><p>作為<strong>項目維護者</strong>，我<strong>最</strong>關心：</p><ul><li>我是<strong>高效的</strong>維護者嗎？ <ul><li><strong>指標：</strong>拉取請求在代碼審查之前等待的時間。</li><li><strong>指標：</strong>代碼審查和後續拉取請求之間的時間。</li><li><strong>指標：</strong>我的代碼審核中有多少被批准？</li><li><strong>指標：</strong>我的代碼評論中有多少被拒絕或返工？</li><li><strong>指標：</strong>代碼審查的評論的情感分析。</li></ul></li><li>我如何讓<strong>更多人</strong>幫助我維護這件事？ <ul><li><strong>指標：</strong>項目貢獻者的社交覆蓋面數量。</li></ul></li><li>我們的<strong>代碼質量</strong>隨着時間的推移變得越來越好嗎？ <ul><li><strong>指標：</strong>計算隨着時間的推移引入的迴歸數量。</li><li><strong>指標：</strong>計算隨着時間推移引入的錯誤數量。</li><li><strong>指標：</strong>錯誤歸檔、拉取請求、代碼審查、合併和發佈之間的時間。</li></ul></li></ul><h3 id="項目開發者和貢獻者" tabindex="-1">項目開發者和貢獻者 <a class="header-anchor" href="#項目開發者和貢獻者" aria-label="Permalink to “項目開發者和貢獻者”">​</a></h3><p>作為<strong>項目開發者或貢獻者</strong>，我<strong>最</strong>關心：</p><ul><li>我可以從為這個項目做出貢獻中獲得哪些有價值的東西，以及實現這個價值需要多長時間？ <ul><li><strong>指標：</strong>下游價值。</li><li><strong>指標：</strong>提交、代碼審查和合並之間的時間。</li></ul></li><li>通過使用我在貢獻中學到的東西來增加工作機是否有良好的前景？ <ul><li><strong>指標：</strong>生活工資。</li></ul></li><li>這個項目有多受歡迎？ <ul><li><strong>指標：</strong>社交媒體帖子、分享和收藏的數量。</li></ul></li><li>社區有影響力的人知道我的項目嗎？ <ul><li><strong>指標：</strong>創始人、維護者和貢獻者的社交範圍。</li></ul></li></ul><p>通過創建這個列表，我們開始讓 CHAOSS 更加豐滿了，並且在今年夏天項目中首次發佈該指標時，我迫不及待地想看看廣泛的開源社區可能有什麼其他偉大的想法，以及我們還可以從這些貢獻中學到什麼（並衡量！）。</p><h3 id="其它角色" tabindex="-1">其它角色 <a class="header-anchor" href="#其它角色" aria-label="Permalink to “其它角色”">​</a></h3><p>接下來，你需要了解有關其他角色（例如基金會、企業開源計劃辦公室、業務風險和法律團隊、人力資源等）以及最終用户的目標問題度量集的更多信息。他們關心開源的不同事物。</p>',9)),i("p",null,[l[18]||(l[18]=t("如果你是開源貢獻者或組成分子，我們邀請你",-1)),r(o,{href:"https://github.com/chaoss/"},{default:n(()=>[...l[17]||(l[17]=[t("來看看這個項目",-1)])]),_:1}),l[19]||(l[19]=t("並參與社區活動！",-1))]),l[42]||(l[42]=i("hr",null,null,-1)),i("p",null,[l[21]||(l[21]=t("via: ",-1)),r(o,{href:"https://opensource.com/article/19/8/measure-project"},{default:n(()=>[...l[20]||(l[20]=[t("https://opensource.com/article/19/8/measure-project",-1)])]),_:1})]),i("p",null,[l[26]||(l[26]=t("作者：",-1)),r(o,{href:"https://opensource.com/users/the3rdlaw"},{default:n(()=>[...l[22]||(l[22]=[t("Jon Lawrence",-1)])]),_:1}),l[27]||(l[27]=t(" 選題：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...l[23]||(l[23]=[t("lujun9972",-1)])]),_:1}),l[28]||(l[28]=t(" 譯者：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...l[24]||(l[24]=[t("wxy",-1)])]),_:1}),l[29]||(l[29]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...l[25]||(l[25]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[32]||(l[32]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[30]||(l[30]=[t("LCTT",-1)])]),_:1}),l[33]||(l[33]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...l[31]||(l[31]=[t("Linux中國",-1)])]),_:1}),l[34]||(l[34]=t(" 榮譽推出",-1))])])}const x=u(p,[["render",m]]);export{h as __pageData,x as default};
